/* @autogenerated */
package net.civeira.phylax.feature.oauth.webauthn.infrastructure.driven;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.MessageDigest;
import java.security.Signature;
import java.security.spec.ECGenParameterSpec;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.webauthn4j.converter.AttestationObjectConverter;
import com.webauthn4j.converter.AuthenticatorDataConverter;
import com.webauthn4j.converter.util.ObjectConverter;
import com.webauthn4j.data.attestation.AttestationObject;
import com.webauthn4j.data.attestation.authenticator.AAGUID;
import com.webauthn4j.data.attestation.authenticator.AttestedCredentialData;
import com.webauthn4j.data.attestation.authenticator.AuthenticatorData;
import com.webauthn4j.data.attestation.authenticator.EC2COSEKey;
import com.webauthn4j.data.attestation.statement.COSEAlgorithmIdentifier;
import com.webauthn4j.data.attestation.statement.NoneAttestationStatement;

import net.civeira.phylax.feature.oauth.webauthn.domain.exception.WebAuthnException;

/**
 * The registration and the assertions of a passkey verified with webauthn4j, against a software
 * authenticator with a real P-256 key.
 */
class WebAuthnVerifierAdapterUnitTest {
  private static final String ORIGIN = "https://idp.example.com";
  private static final String RP_ID = "idp.example.com";
  private static final byte UP = 0x01;
  private static final byte UV = 0x04;
  private static final byte AT = 0x40;

  private final WebAuthnVerifierAdapter verifier = new WebAuthnVerifierAdapter();
  private final ObjectConverter converter = new ObjectConverter();
  private final byte[] credentialId = UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8);
  private final AAGUID aaguid = new AAGUID(UUID.randomUUID());
  private KeyPair keys;

  @BeforeEach
  void setUp() throws Exception {
    KeyPairGenerator generator = KeyPairGenerator.getInstance("EC");
    generator.initialize(new ECGenParameterSpec("secp256r1"));
    keys = generator.generateKeyPair();
  }

  private static String b64(byte[] bytes) {
    return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
  }

  private static byte[] sha256(byte[] bytes) throws Exception {
    return MessageDigest.getInstance("SHA-256").digest(bytes);
  }

  private static String challenge() {
    return b64(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8));
  }

  private static byte[] clientData(String type, String challenge, String origin) {
    return ("{\"type\":\"" + type + "\",\"challenge\":\"" + challenge + "\",\"origin\":\"" + origin
        + "\",\"crossOrigin\":false}").getBytes(StandardCharsets.UTF_8);
  }

  /** The credential that a browser sends when the authenticator creates a passkey. */
  private Map<String, Object> registration(String challenge, String origin) throws Exception {
    AttestedCredentialData attested = new AttestedCredentialData(aaguid, credentialId,
        EC2COSEKey.create(keys, COSEAlgorithmIdentifier.ES256));
    AttestationObject attestation = new AttestationObject(
        new AuthenticatorData<>(sha256(RP_ID.getBytes(StandardCharsets.UTF_8)),
            (byte) (UP | UV | AT), 0, attested),
        new NoneAttestationStatement());
    Map<String, Object> response = new HashMap<>();
    response.put("attestationObject",
        b64(new AttestationObjectConverter(converter).convertToBytes(attestation)));
    response.put("clientDataJSON", b64(clientData("webauthn.create", challenge, origin)));
    Map<String, Object> credential = new HashMap<>();
    credential.put("id", b64(credentialId));
    credential.put("response", response);
    credential.put("transports", List.of("internal"));
    return credential;
  }

  /** The credential that a browser sends when the authenticator signs a login challenge. */
  private Map<String, Object> assertion(String challenge, long counter) throws Exception {
    return assertion(challenge, counter, (byte) (UP | UV));
  }

  /** The same, with the given authenticator flags. */
  private Map<String, Object> assertion(String challenge, long counter, byte flags)
      throws Exception {
    byte[] authenticatorData = new AuthenticatorDataConverter(converter).convert(
        new AuthenticatorData<>(sha256(RP_ID.getBytes(StandardCharsets.UTF_8)), flags, counter));
    byte[] clientData = clientData("webauthn.get", challenge, ORIGIN);
    ByteArrayOutputStream signed = new ByteArrayOutputStream();
    signed.write(authenticatorData);
    signed.write(sha256(clientData));
    Signature signature = Signature.getInstance("SHA256withECDSA");
    signature.initSign(keys.getPrivate());
    signature.update(signed.toByteArray());
    Map<String, Object> response = new HashMap<>();
    response.put("authenticatorData", b64(authenticatorData));
    response.put("clientDataJSON", b64(clientData));
    response.put("signature", b64(signature.sign()));
    response.put("userHandle", b64("user-1".getBytes(StandardCharsets.UTF_8)));
    Map<String, Object> credential = new HashMap<>();
    credential.put("id", b64(credentialId));
    credential.put("response", response);
    return credential;
  }

  private String register() throws Exception {
    String challenge = challenge();
    return (String) verifier
        .verifyRegistration(registration(challenge, ORIGIN), challenge, ORIGIN, RP_ID)
        .get("publicKey");
  }

  @Test
  @DisplayName("A registration gives the id, the public key, the counter and the authenticator")
  void registration_verified() throws Exception {
    String challenge = challenge();

    Map<String, Object> result =
        verifier.verifyRegistration(registration(challenge, ORIGIN), challenge, ORIGIN, RP_ID);

    Assertions.assertEquals(b64(credentialId), result.get("credentialId"));
    Assertions.assertNotNull(result.get("publicKey"));
    Assertions.assertEquals(0, result.get("signCount"));
    Assertions.assertEquals(aaguid.getValue().toString(), result.get("aaguid"));
    Assertions.assertEquals(List.of("internal"), result.get("transports"));
  }

  @Test
  @DisplayName("A registration for another challenge or origin is rejected")
  void registration_rejected() throws Exception {
    String challenge = challenge();

    Assertions.assertThrows(WebAuthnException.class, () -> verifier
        .verifyRegistration(registration(challenge, ORIGIN), challenge(), ORIGIN, RP_ID));
    Assertions.assertThrows(WebAuthnException.class,
        () -> verifier.verifyRegistration(registration(challenge, "https://evil.example.com"),
            challenge, ORIGIN, RP_ID));
    Assertions.assertThrows(WebAuthnException.class,
        () -> verifier.verifyRegistration(Map.of(), challenge, ORIGIN, RP_ID));
  }

  @Test
  @DisplayName("An assertion signed by the registered key gives the new counter")
  void assertion_verified() throws Exception {
    String publicKey = register();
    String challenge = challenge();

    Assertions.assertEquals(1,
        verifier.verifyAssertion(assertion(challenge, 1), challenge, ORIGIN, RP_ID, publicKey, 0));
    Assertions.assertEquals(6,
        verifier.verifyAssertion(assertion(challenge, 6), challenge, ORIGIN, RP_ID, publicKey, 5));
  }

  @Test
  @DisplayName("An assertion that does not advance the counter is a replay")
  void assertion_replay() throws Exception {
    String publicKey = register();
    String challenge = challenge();

    Assertions.assertThrows(WebAuthnException.class, () -> verifier
        .verifyAssertion(assertion(challenge, 5), challenge, ORIGIN, RP_ID, publicKey, 5));
  }

  @Test
  @DisplayName("An assertion for another challenge or key is rejected")
  void assertion_rejected() throws Exception {
    String publicKey = register();
    String challenge = challenge();
    Map<String, Object> signed = assertion(challenge, 1);
    setUp();
    String otherKey = register();

    Assertions.assertThrows(WebAuthnException.class,
        () -> verifier.verifyAssertion(signed, challenge(), ORIGIN, RP_ID, publicKey, 0));
    Assertions.assertThrows(WebAuthnException.class,
        () -> verifier.verifyAssertion(signed, challenge, ORIGIN, RP_ID, otherKey, 0));
  }

  @Test
  @DisplayName("An assertion without user verification is rejected")
  void assertion_without_user_verification() throws Exception {
    String publicKey = register();
    String challenge = challenge();

    Assertions.assertThrows(WebAuthnException.class, () -> verifier
        .verifyAssertion(assertion(challenge, 1, UP), challenge, ORIGIN, RP_ID, publicKey, 0));
  }
}
